import { spawn } from 'node:child_process';
import { once } from 'node:events';

export async function launch(databasePath) {
  const child = spawn(process.execPath, ['server.js'], {
    cwd: new URL('../', import.meta.url),
    env: { ...process.env, PORT: '0', DB_PATH: databasePath },
    stdio: ['ignore', 'pipe', 'pipe'],
  });
  let output = '';
  let errors = '';
  child.stderr.on('data', (chunk) => { errors += chunk; });
  const baseUrl = await new Promise((resolve, reject) => {
    const timer = setTimeout(() => {
      child.kill();
      reject(new Error(`Server did not start: ${errors}`));
    }, 5000);
    child.once('error', (error) => { clearTimeout(timer); reject(error); });
    child.once('exit', (code) => {
      clearTimeout(timer);
      reject(new Error(`Server exited with ${code}: ${errors}`));
    });
    child.stdout.on('data', (chunk) => {
      output += chunk;
      const match = output.match(/Workboard listening on 0\.0\.0\.0:(\d+)/);
      if (match) {
        clearTimeout(timer);
        resolve(`http://127.0.0.1:${match[1]}`);
      }
    });
  });
  return {
    baseUrl,
    async stop() {
      if (child.exitCode !== null || child.signalCode !== null) return;
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    },
  };
}

import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { launch } from './server-helper.js';

test('project validation, navigation, creation order, and process restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const databasePath = join(directory, 'nested', 'projects.sqlite');
  let running;
  try {
    running = await launch(databasePath);
    const get = (path) => fetch(`${running.baseUrl}${path}`);
    const create = (name) => fetch(`${running.baseUrl}/projects`, {
      method: 'POST',
      body: new URLSearchParams({ name }),
      redirect: 'manual',
    });

    const health = await get('/health');
    assert.equal(health.status, 200);
    assert.deepEqual(await health.json(), { status: 'ok' });

    const initial = await (await get('/')).text();
    assert.match(initial, /<h1>Workboard<\/h1>/);
    assert.match(initial, /<label for="project-name">Project name<\/label>/);
    assert.match(initial, />Create project<\/button>/);
    assert.doesNotMatch(initial, /data-testid="project-row"/);

    for (const name of ['', ' \t\n ']) {
      const invalid = await create(name);
      assert.equal(invalid.status, 400);
      const page = await invalid.text();
      assert.match(page, /role="alert">Project name is required/);
      assert.doesNotMatch(page, /data-testid="project-row"/);
    }

    const created = await create('  First project  ');
    assert.equal(created.status, 303);
    assert.equal(created.headers.get('location'), '/');
    assert.equal((await create('Second <project> & "team"')).status, 303);

    const list = await (await get('/')).text();
    assert.equal((list.match(/data-testid="project-row"/g) ?? []).length, 2);
    assert.match(list, /class="project-name">First project<\/span>/);
    assert.match(list, /Second &lt;project&gt; &amp; &quot;team&quot;/);
    assert.ok(list.indexOf('First project') < list.indexOf('Second &lt;project&gt;'));
    const ids = [...list.matchAll(/action="\/projects\/(\d+)"/g)].map((match) => match[1]);
    assert.equal(ids.length, 2);
    assert.notEqual(ids[0], ids[1]);
    const detail = await (await get(`/projects/${ids[0]}`)).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/" method="get"/);
    assert.match(detail, />Projects<\/button>/);
    assert.equal((await get('/projects/99999')).status, 404);
    assert.equal((await get('/projects/9007199254740993')).status, 404);

    const invalidAfterCreation = await (await create('   ')).text();
    assert.equal((invalidAfterCreation.match(/data-testid="project-row"/g) ?? []).length, 2);

    await running.stop();
    running = await launch(databasePath);
    assert.equal(await (await get('/')).text(), list);
    assert.equal(await (await get(`/projects/${ids[0]}`)).text(), detail);
    assert.equal((await create('Third project')).status, 303);
    const afterRestart = await (await get('/')).text();
    assert.equal((afterRestart.match(/data-testid="project-row"/g) ?? []).length, 3);
    assert.ok(afterRestart.indexOf('Third project') > afterRestart.indexOf('Second &lt;project&gt;'));
  } finally {
    await running?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});
import test from 'node:test';
import assert from 'node:assert/strict';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { launch } from './server-helper.js';

function taskRows(html) {
  return [...html.matchAll(/<article class="task-row" data-testid="task-row">([\s\S]*?)<\/article>/g)]
    .map((match) => match[1]);
}

test('tasks validate, stay within their project, filter, and persist completion across process restarts', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-tasks-'));
  let running;
  try {
    const databasePath = join(directory, 'workboard.sqlite');
    running = await launch(databasePath);
    const get = async (path) => (await fetch(`${running.baseUrl}${path}`)).text();
    const post = (path, values) => fetch(`${running.baseUrl}${path}`, {
      method: 'POST', body: new URLSearchParams(values), redirect: 'manual',
    });
    await post('/projects', { name: 'First' });
    await post('/projects', { name: 'Second' });

    const empty = await get('/projects/1');
    assert.match(empty, /<label for="task-title">Task title<\/label>/);
    assert.match(empty, />Create task<\/button>/);
    assert.match(empty, /<label for="task-filter">Task filter<\/label>/);
    assert.match(empty, /<option selected>All<\/option><option>Open<\/option><option>Completed<\/option>/);
    assert.equal(taskRows(empty).length, 0);
    for (const title of ['', ' \t\n ']) {
      const invalid = await post('/projects/1/tasks', { title });
      assert.equal(invalid.status, 400);
      const html = await invalid.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.equal(taskRows(html).length, 0);
    }

    const created = await post('/projects/1/tasks', { title: '  First task  ' });
    assert.equal(created.status, 303);
    assert.equal(created.headers.get('location'), '/projects/1?filter=All');
    await post('/projects/1/tasks', { title: 'Second <task> & "team"' });
    await post('/projects/2/tasks', { title: 'Other project task' });
    const rows = taskRows(await get('/projects/1'));
    assert.equal(rows.length, 2);
    assert.match(rows[0], /class="task-title">First task<\/span>/);
    assert.match(rows[0], /type="checkbox" name="completed" aria-label="Complete First task"/);
    assert.doesNotMatch(rows[0], / checked/);
    assert.match(rows[1], /Complete Second &lt;task&gt; &amp; &quot;team&quot;/);
    assert.doesNotMatch(await get('/projects/1'), /Other project task/);
    assert.doesNotMatch(await get('/projects/2'), /First task/);

    const invalid = await post('/projects/1/tasks', { title: '  ' });
    assert.equal(taskRows(await invalid.text()).length, 2);
    assert.equal((await post('/projects/2/tasks/1/completion', { completed: 'on' })).status, 404);
    assert.equal((await post('/projects/999/tasks', { title: 'Missing project' })).status, 404);
    assert.equal((await post('/projects/1/tasks/999/completion', { completed: 'on' })).status, 404);
    assert.equal((await post('/projects/1/tasks/9007199254740993/completion', { completed: 'on' })).status, 404);
    assert.equal(taskRows(await get('/projects/1?filter=Completed')).length, 0);

    const completed = await post('/projects/1/tasks/1/completion', { completed: 'on', filter: 'Open' });
    assert.equal(completed.status, 303);
    assert.equal(completed.headers.get('location'), '/projects/1?filter=Open');
    const saved = await get('/projects/1');
    assert.match(taskRows(saved)[0], / checked/);
    const openRows = taskRows(await get('/projects/1?filter=Open'));
    assert.equal(openRows.length, 1);
    assert.match(openRows[0], /Second &lt;task&gt;/);
    const completedPage = await get('/projects/1?filter=Completed');
    assert.match(completedPage, /<option selected>Completed<\/option>/);
    assert.equal(taskRows(completedPage).length, 1);
    assert.match(taskRows(completedPage)[0], /First task/);
    assert.equal(taskRows(await get('/projects/1?filter=invalid')).length, 2);

    await running.stop();
    running = await launch(databasePath);
    assert.equal(await get('/projects/1'), saved);
    assert.equal(await get('/projects/1?filter=Completed'), completedPage);
    await post('/projects/1/tasks/1/completion', {});
    assert.equal(taskRows(await get('/projects/1?filter=Open')).length, 2);
    assert.equal(taskRows(await get('/projects/1?filter=Completed')).length, 0);
    await running.stop();
    running = await launch(databasePath);
    assert.doesNotMatch(taskRows(await get('/projects/1'))[0], / checked/);
  } finally {
    await running?.stop();
    await rm(directory, { recursive: true, force: true });
  }
});
# Workboard

Requires Node.js 22.22.1. There are no application dependencies to install.

```sh
npm start
```

The server binds to `0.0.0.0` at `PORT` (default `8080`). Set `DB_PATH` to the
SQLite file to use (default `data/workboard.sqlite`). Its parent directory is
created automatically. Keep this file to preserve projects, tasks, and completion
state between restarts.

```sh
PORT=8080 DB_PATH=data/workboard.sqlite npm start
npm test
```

`GET /health` returns HTTP 200 with `{"status":"ok"}`. Project creation and
navigation use ordinary browser forms. Names are trimmed before persistence;
blank names return a visible validation alert without creating a project.
Each project has its own tasks. Titles are trimmed and blank titles show a
validation alert. Checkboxes save completion immediately; the task filter shows
All (the default), Open, or Completed tasks in creation order. Direct project
URLs remain usable after reloads and restarts.
